import { useEffect, useState } from "react";

function Attendance() {
  const [students, setStudents] = useState([]);
  const [date, setDate] = useState("");
  const [attendance, setAttendance] = useState({});

  // Load students
  useEffect(() => {
    const storedStudents = JSON.parse(localStorage.getItem("students")) || [];
    setStudents(storedStudents);
  }, []);

  // Mark present / absent for individual student
  const markAttendance = (studentId, status) => {
    setAttendance({
      ...attendance,
      [studentId]: status
    });
  };

  // Save attendance
  const saveAttendance = () => {
    if (!date) {
      alert("Please select a date");
      return;
    }

    const storedAttendance = JSON.parse(localStorage.getItem("attendance")) || {};

    students.forEach(student => {
      if (!storedAttendance[student.id]) {
        storedAttendance[student.id] = {};
      }
      storedAttendance[student.id][date] =
        attendance[student.id] || "Absent";
    });

    localStorage.setItem("attendance", JSON.stringify(storedAttendance));
    alert("Attendance saved successfully");
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Student Attendance</h2>

      <input
        type="date"
        value={date}
        onChange={e => setDate(e.target.value)}
      />
      <br /><br />

      {students.length === 0 && <p>No students found</p>}

      {students.map(student => (
        <div
          key={student.id}
          style={{
            border: "1px solid #ccc",
            padding: "10px",
            marginBottom: "8px"
          }}
        >
          <b>{student.name}</b> (Roll: {student.roll})
          <br />

          <button onClick={() => markAttendance(student.id, "Present")}>
            Present
          </button>

          <button onClick={() => markAttendance(student.id, "Absent")}>
            Absent
          </button>

          <span style={{ marginLeft: "10px" }}>
            Status: {attendance[student.id] || "Not marked"}
          </span>
        </div>
      ))}

      <br />
      <button onClick={saveAttendance}>Save Attendance</button>
    </div>
  );
}

export default Attendance;
